import React, { useState, useEffect, useRef } from "react";
import axios from "axios";
import { Client } from "@stomp/stompjs";
import SockJS from "sockjs-client";
import { useNavigate } from "react-router-dom";

export default function Match({ onGameStart }) {
  const [entryFee, setEntryFee] = useState(13);
  const [status, setStatus] = useState("");
  const [game, setGame] = useState(null);
  const [playerId, setPlayerId] = useState(null);
  const [loading, setLoading] = useState(false);

  const stompClientRef = useRef(null);
  const navigate = useNavigate();
  const ALLOWED_FEES = [13, 23, 50];

  // লগইন করা ইউজারের gameId
  const myGameId = localStorage.getItem("myGameId");

  // প্রথমে চেক করব আগে থেকে ম্যাচ আছে কিনা
  useEffect(() => {
    const checkExistingMatch = async () => {
      const token = localStorage.getItem("authToken");
      try {
        const res = await axios.get("http://localhost:8080/api/match/status", {
          headers: { Authorization: `Bearer ${token}` },
        });
        if (res.data?.id) {
          setGame(res.data);
          setStatus("⚠️ আগের একটি ম্যাচ পাওয়া গেছে, যুক্ত হচ্ছি...");
        }
      } catch (err) {
        console.warn("❗ আগের ম্যাচ চেক করতে সমস্যা:", err);
      }
    };
    checkExistingMatch();
  }, []);

  // WebSocket সংযোগ সেটআপ
  useEffect(() => {
    if (!game?.id) return;

    const token = localStorage.getItem("authToken");
    const socket = new SockJS(`http://localhost:8080/ludo-ws?token=${token}`);
    const client = new Client({
      webSocketFactory: () => socket,
      debug: (msg) => console.log("WS:", msg),
      onConnect: () => {
        console.log("🟢 Connected to WebSocket");
        client.subscribe(`/topic/match/${game.id}`, (message) => {
          const updatedGame = JSON.parse(message.body);
          setGame(updatedGame);

          // যদি ম্যাচ ক্যানসেল হয়
          if (updatedGame.status === "CANCELLED") {
            setStatus("❌ ম্যাচ অটো-ক্যানসেল হয়েছে");
            return;
          }

          // প্লেয়ার সনাক্ত
          if (updatedGame.player1?.gameId === myGameId) {
            setPlayerId(1);
          } else if (updatedGame.player2?.gameId === myGameId) {
            setPlayerId(2);
          }

          // দুইজন প্লেয়ার হলে সরাসরি গেম শুরু
          if (updatedGame.player1 && updatedGame.player2) {
            localStorage.setItem("currentSessionId", updatedGame.id);
            localStorage.setItem("playerId", playerId || 1);
            localStorage.setItem("entryFee", entryFee);

            onGameStart({
              gameId: updatedGame.id,
              playerId: playerId || 1,
              entryFee,
            });

            setTimeout(() => {
              navigate("/game");
            }, 500);
          }
        });
      },
    });

    client.activate();
    stompClientRef.current = client;

    return () => {
      if (client) client.deactivate();
    };
  }, [game?.id, myGameId, entryFee, playerId, navigate, onGameStart]);

  // নতুন ম্যাচ রিকোয়েস্ট
  const handleMatchRequest = async () => {
    if (!ALLOWED_FEES.includes(entryFee)) {
      setStatus("❌ ভুল এন্ট্রি ফি");
      return;
    }
    setLoading(true);
    setStatus("🔍 প্রতিপক্ষ খুঁজছি...");

    const token = localStorage.getItem("authToken");
    try {
      const res = await axios.post(
        "http://localhost:8080/api/match/start",
        { entryFee },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      setGame(res.data);
    } catch (err) {
      setStatus("⚠️ সার্ভার সমস্যা: " + (err.response?.data?.error || "Unknown error"));
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-lg mx-auto mt-12 p-6 bg-white border rounded-xl shadow-lg">
      <h2 className="text-2xl font-bold text-center text-indigo-700 mb-6">🎲 লুডু ম্যাচ</h2>

      <select
        value={entryFee}
        onChange={(e) => setEntryFee(Number(e.target.value))}
        disabled={loading}
        className="w-full mb-4 border rounded px-4 py-2"
      >
        {ALLOWED_FEES.map((fee) => (
          <option key={fee} value={fee}>
            ৳ {fee}
          </option>
        ))}
      </select>

      <button
        onClick={handleMatchRequest}
        disabled={loading}
        className={`w-full py-2 px-4 text-white font-semibold rounded ${
          loading ? "bg-gray-400" : "bg-indigo-600 hover:bg-indigo-700"
        }`}
      >
        {loading ? "⏳ খুঁজছি..." : "🔍 প্রতিপক্ষ খুঁজুন"}
      </button>

      {status && <p className="mt-4 text-center text-sm text-gray-700">{status}</p>}
    </div>
  );
}
